from itertools import combinations

def can_form_equal_teams(scores):
    total_score = sum(scores)
    if total_score % 2 != 0:
        return "NO"

    target_score = total_score // 2

    for combo in combinations(scores, 3):
        if sum(combo) == target_score:
            remaining_scores = [s for s in scores if s not in combo]
            if any(sum(comb) == target_score for comb in combinations(remaining_scores, 3)):
                return "YES"
    return "NO"

