def can_form_equal_teams(scores):
    total_score = sum(scores)
    if total_score % 2 != 0:
        return "NO"

    target = total_score // 2
    n = len(scores)

    def dfs(index, current_sum, count):
        if count == 3 and current_sum == target:
            return True
        if index == n or current_sum > target or count > 3:
            return False

        return dfs(index + 1, current_sum + scores[index], count + 1) or dfs(index + 1, current_sum, count)

    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            visited[i] = True
            for j in range(i+1, n):
                if not visited[j]:
                    visited[j] = True
                    for k in range(j+1, n):
                        if not visited[k]:
                            visited[k] = True
                            if dfs(k, scores[i] + scores[j] + scores[k], 3):
                                return "YES"
                            visited[k] = False
                    visited[j] = False
            visited[i] = False

    return "NO"

